&lt;p style=&quot;color: !important;&quot;&gt;&lt;span style=&quot;color: #262626;&quot;&gt;&lt;strong&gt;KNOWLEDGE, SKILLS, AND ABILITIES:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;color: #262626;&quot;&gt;Proven leadership experience&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;color: #262626;&quot;&gt;Able to take on projects with little supervision.&lt;/span&gt;&lt;/li&gt;
