&lt;p&gt;&lt;span style=&quot;color: #272700;&quot;&gt;• &lt;/span&gt;&lt;span style=&quot;color: #000000;&quot;&gt;Understands &lt;/span&gt;&lt;span style=&quot;color: #020200;&quot;&gt;when &lt;/span&gt;&lt;span style=&quot;color: #111100;&quot;&gt;and &lt;/span&gt;&lt;span style=&quot;color: #000000;&quot;&gt;how to escalate issues appropriately.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
